var data = msg.payload;
data.received = new Date().toISOString();

// Tugas 1: Cek batas suhu (threshold)
var threshold = flow.get('threshold');
if (threshold === undefined) threshold = 30;
data.threshold = threshold;
data.alert = data.suhu > threshold;
data.alertMessage = data.alert
    ? `PERINGATAN: Suhu ${data.suhu}°C melewati batas ${threshold}°C!`
    : null;

flow.set('lastSensor', data);

// Output 1 -> Debug & WebSocket (Tugas 4)
var wsMsg = { payload: data };

// Output 2 -> Insert ke SQLite (Tugas 5)
var sqlMsg = {
    topic: `INSERT INTO sensor_history (suhu, kelembaban, timestamp, received) VALUES (${Number(data.suhu)}, ${Number(data.kelembaban)}, '${data.timestamp}', '${data.received}');`
};

return [wsMsg, sqlMsg];

const VALID_KEY = 'iot-secret-123';
const apiKey = msg.req.headers['x-api-key'];
if (apiKey !== VALID_KEY) {
    msg.statusCode = 401;
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    msg.payload = { status: 'error', message: 'Unauthorized: Invalid X-API-Key' };
    return [null, msg];
}
return [msg, null];

var data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
msg.payload = {
    status: 'success',
    data: data,
    threshold: flow.get('threshold') ?? 30,
    server_time: new Date().toISOString()
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return msg;

