return [msg, null];

var body = msg.payload;
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = {'Access-Control-Allow-Origin': '*'};
    return [msg, null];
}
var mqttMsg = {payload: body, topic: 'iot/kontrol'};
node.send([null, mqttMsg]);
msg.statusCode = 200;
msg.payload = {
    status: 'success',
    message: 'Perintah terkirim',
    sent: body
};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [msg, null];

const VALID_KEY = 'iot-secret-123';
const apiKey = msg.req.headers['x-api-key'];
if (apiKey !== VALID_KEY) {
    msg.statusCode = 401;
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    msg.payload = { status: 'error', message: 'Unauthorized: Invalid X-API-Key' };
    return [null, msg];
}
return [msg, null];

const val = Number(msg.payload.threshold);
if (isNaN(val)) {
    msg.statusCode = 400;
    msg.headers = { 'Access-Control-Allow-Origin': '*' };
    msg.payload = { status: 'error', message: 'threshold harus berupa angka' };
    return msg;
}
flow.set('threshold', val);
msg.statusCode = 200;
msg.headers = { 'Access-Control-Allow-Origin': '*' };
msg.payload = { status: 'success', threshold: val, message: 'Threshold diperbarui' };
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
